-- Zonele biogeografice ale Terrei: 20 grile de gândire critică — clasa a 9-a, topic geografie-fizica, pozițiile 181–200
-- Bazate pe lecția „Zonele biogeografice ale Terrei" (relația climă -> vegetație -> faună -> sol).

-- 181
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a01','9','geografie-fizica','published',1,181,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a01','ro','De ce pădurea ecuatorială are cel mai mare număr de specii de plante și animale de pe glob?',
'["Pentru că solurile feralsolice roșii sunt foarte fertile.","Pentru că este cald și umed tot anul, fără un sezon nefavorabil care să oprească creșterea plantelor.","Pentru că se află la altitudine mare, unde este răcoare.","Pentru că iarna lungă elimină speciile slabe."]',
'Fără iarnă și fără secetă, plantele cresc neîntrerupt tot anul — de aceea diversitatea este maximă. Solurile ei sunt, de fapt, sărace, nu bogate.');

-- 182
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a02','9','geografie-fizica','published',2,182,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a02','ro','Un elev spune: „Solul roșu și gros din pădurea ecuatorială trebuie să fie foarte fertil." De ce se înșală?',
'["Are dreptate: un sol gros și roșu este întotdeauna fertil.","Culoarea roșie arată o cantitate mare de humus.","Ploile bogate spală permanent substanțele hrănitoare, iar rezerva de hrană a pădurii stă în vegetație, nu în sol.","Solul este de fapt foarte subțire acolo."]',
'Sub ploile ecuatoriale nutrienții sunt spălați din sol (lateritizare). Bogăția pădurii se sprijină pe reciclarea rapidă a materiei din vegetație, nu pe sol.');

-- 183
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a03','9','geografie-fizica','published',2,183,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a03','ro','În savană cresc ierburi înalte cu arbori izolați, nu o pădure deasă. Care este cauza principală?',
'["Fiindcă solul este prea sărat pentru copaci.","Fiindcă temperaturile sunt prea scăzute pentru pădure.","Fiindcă alternanța dintre un sezon ploios și unul secetos nu îngăduie o pădure deasă, ci ierburi cu arbori răzleți.","Fiindcă oamenii au tăiat pădurea inițială."]',
'În savană plouă doar o parte din an. Seceta sezonieră usucă solul, iar copacii nu pot forma o pădure continuă — rămân ierburile și pâlcurile de arbori.');

-- 184
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a04','9','geografie-fizica','published',3,184,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a04','ro','Dacă o secetă îndelungată ar distruge ierburile din savană, ce s-ar întâmpla cel mai probabil cu leii?',
'["Leii nu ar fi afectați, pentru că mănâncă și plante.","Leii s-ar muta în pădurea ecuatorială.","Leii ar începe să pască iarbă în locul cărnii.","Numărul erbivorelor ar scădea, deci ar scădea și leii, fiindcă fauna depinde de vegetație."]',
'Lanțul este climă -> vegetație -> faună. Ierburile hrănesc erbivorele (zebre, antilope), iar acestea hrănesc răpitoarele. Fără iarbă se prăbușește tot lanțul.');

-- 185
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a05','9','geografie-fizica','published',0,185,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a05','ro','Plantele mediteraneene (măslinul, stejarul de plută) au frunze mici, tari și cerate, veșnic verzi. La ce condiție s-au adaptat în primul rând?',
'["La vara caldă și secetoasă, ca să piardă cât mai puțină apă.","La gerul aspru al iernii.","La lipsa de lumină solară.","La nevoia de a crește foarte repede."]',
'În zona mediteraneană vara este secetoasă. Frunzele mici, tari și cerate reduc pierderea apei — o adaptare la secetă, nu la ger.');

-- 186
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a06','9','geografie-fizica','published',1,186,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a06','ro','De ce pădurea de foioase își pierde frunzele iarna, iar coniferele din taiga rămân verzi?',
'["Fiindcă în taiga nu este niciodată frig.","Foioasele își leapădă frunzele late ca să treacă peste iarna rece, iar coniferele, cu frunze-ace rezistente la ger, rămân verzi.","Fiindcă foioasele sunt copaci mult mai bătrâni.","Fiindcă animalele mănâncă acele coniferelor."]',
'Frunza lată pierde multă apă și ar îngheța iarna, așa că foioasele o leapădă. Acele coniferelor rezistă la ger și le lasă să folosească orice zi mai blândă.');

-- 187
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a07','9','geografie-fizica','published',3,187,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a07','ro','În stepă cresc ierburi, nu copaci. Care este explicația?',
'["Fiindcă solul (cernoziomul) este prea sărac pentru copaci.","Fiindcă în stepă este mereu prea cald pentru arbori.","Fiindcă vântul puternic dezrădăcinează orice copac.","Fiindcă precipitațiile (250–500 mm/an) sunt prea puține pentru pădure, dar ajung pentru ierburi."]',
'Pragul dintre pădure și stepă îl dă apa. Sub un anumit nivel de precipitații copacii nu se mai pot menține, dar ierburile, cu rădăcini superficiale, rezistă.');

-- 188
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a08','9','geografie-fizica','published',2,188,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a08','ro','Cernoziomurile de stepă sunt cele mai fertile soluri de pe glob. De ce?',
'["Fiindcă ploile abundente aduc mereu minerale noi.","Fiindcă provin din lave vulcanice.","Fiindcă ierburile bogate lasă mult humus, iar clima relativ uscată nu îl spală în adânc.","Fiindcă sunt înghețate cea mai mare parte a anului."]',
'Cernoziomurile se formează sub ierburile de stepă: rădăcinile lasă mult humus, iar climatul uscat împiedică spălarea lui — de aceea sunt cele mai fertile.');

-- 189
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a09','9','geografie-fizica','published',1,189,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a09','ro','Pădurea ecuatorială primește foarte multă ploaie, dar are sol sărac; stepa primește puțină ploaie, dar are sol bogat. Cum se explică acest paradox?',
'["Este o greșeală: mai multă ploaie înseamnă întotdeauna sol mai bun.","Ploaia multă spală substanțele hrănitoare din sol, pe când clima mai uscată a stepei le păstrează și adună humus.","Pentru că stepa se află mai aproape de Ecuator.","Pentru că în pădurea ecuatorială nu cresc deloc plante."]',
'Contraintuitiv, dar adevărat: excesul de apă sărăcește solul prin spălare, în timp ce uscăciunea moderată a stepei permite acumularea humusului (cernoziom).');

-- 190
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a10','9','geografie-fizica','published',0,190,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a10','ro','Cămila bactriană din deșerturile Asiei Centrale (Gobi) are blană groasă, spre deosebire de cămila din Sahara. De ce?',
'["Fiindcă deșerturile temperate din Asia Centrală au ierni foarte geroase, nu doar veri calde.","Fiindcă este o specie mult mai bătrână.","Fiindcă în Gobi plouă abundent tot anul.","Fiindcă se hrănește numai cu zăpadă."]',
'Deșert înseamnă lipsă de apă, nu neapărat căldură. Deșerturile temperate (Gobi) au ierni geroase, așa că fauna lor, precum cămila bactriană, are blană groasă.');

-- 191
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a11','9','geografie-fizica','published',3,191,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a11','ro','În tundră cresc mesteacăn pitic și salcie pitică — plante mărunte, lipite de pământ. Care este cauza principală?',
'["Fiindcă erbivorele le pasc fără încetare.","Fiindcă solul este mult prea fertil.","Fiindcă primesc prea multă lumină vara.","Fiindcă frigul, sezonul scurt de vegetație și solul înghețat în adâncime nu le permit să crească înalte."]',
'În tundră vara este scurtă și răcoroasă, iar solul rămâne înghețat dedesubt. Plantele se fac mărunte și lipite de pământ ca să reziste vântului și frigului.');

-- 192
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a12','9','geografie-fizica','published',1,192,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a12','ro','De ce copacii înalți nu pot prinde rădăcini în tundră?',
'["Fiindcă vântul îi rupe imediat ce răsar.","Fiindcă stratul de sol înghețat permanent (permafrost) împiedică rădăcinile adânci și scurgerea apei.","Fiindcă acolo este prea cald pentru copaci.","Fiindcă lipsește complet lumina în tot cursul anului."]',
'Permafrostul este un strat înghețat care nu se dezgheață. Rădăcinile nu îl pot străpunge, iar apa băltește deasupra — de aceea în tundră cresc doar plante mici.');

-- 193
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a13','9','geografie-fizica','published',2,193,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a13','ro','Pe uscatul Antarcticii cresc doar licheni și mușchi, totuși aici trăiesc mulți pinguini, foci și albatroși. De unde își iau hrana?',
'["Din lichenii și mușchii de pe uscat.","Din plante aduse de vânt din alte zone.","Din ocean — bogăția vieții antarctice depinde de hrana din apă, nu de vegetația de uscat.","Nu se hrănesc deloc în timpul iernii."]',
'Aici lanțul obișnuit se schimbă: uscatul e aproape gol, dar oceanul e bogat. Pinguinii, focile și albatroșii trăiesc din pește și krill — viața se sprijină pe mare.');

-- 194
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a14','9','geografie-fizica','published',0,194,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a14','ro','De ce zonele biogeografice se succed în fâșii, de la Ecuator spre poli (zonalitate latitudinală)?',
'["Fiindcă Soarele încălzește inegal Pământul (mult la Ecuator, puțin la poli), deci temperatura și precipitațiile se schimbă cu latitudinea.","Fiindcă solurile sunt aranjate din natură în fâșii colorate.","Fiindcă vânturile bat numai dinspre nord.","Fiindcă Pământul este mai vechi la poli decât la Ecuator."]',
'Cauza de bază este energia solară primită inegal. Ea comandă clima, iar clima comandă vegetația și fauna — de aceea zonele se succed ordonat de la Ecuator la poli.');

-- 195
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a15','9','geografie-fizica','published',3,195,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a15','ro','Un munte foarte înalt situat chiar pe Ecuator poate avea zăpadă în vârf. Cum se explică, deși este la Ecuator?',
'["Fiindcă, de fapt, la Ecuator este foarte frig.","Fiindcă zăpada este adusă cu vântul tocmai de la poli.","Fiindcă la Ecuator noaptea durează șase luni.","Fiindcă temperatura scade cu altitudinea, așa că pe verticală apar etaje asemănătoare zonelor de la Ecuator spre poli."]',
'Este etajarea altitudinală: urcând pe munte devine tot mai frig, iar vegetația se schimbă în etaje — ca și cum ai călători de la Ecuator spre pol, dar pe verticală.');

-- 196
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a16','9','geografie-fizica','published',1,196,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a16','ro','De ce o parte dintre arborii pădurii musonice își pierd frunzele, în timp ce pădurea ecuatorială rămâne mereu verde?',
'["Fiindcă este mult mai rece decât pădurea ecuatorială.","Fiindcă are un sezon secetos (musonii aduc ploaie doar vara), iar în perioada uscată arborii își leapădă frunzele.","Fiindcă solul ei este nisipos și sărac.","Fiindcă primește ploi abundente în tot cursul anului."]',
'Spre deosebire de pădurea ecuatorială, udă tot anul, pădurea musonică are un sezon uscat. Ca să economisească apă, o parte dintre arbori își pierd frunzele atunci.');

-- 197
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a17','9','geografie-fizica','published',0,197,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a17','ro','În deșerturile calde vegetația este rară și xerofită. Care este factorul care limitează cel mai mult viața plantelor?',
'["Precipitațiile foarte reduse — doar plantele adaptate la secetă (xerofite) pot trăi.","Frigul, care este prea aspru pentru plante.","Solul prea fertil, care îneacă rădăcinile.","Animalele, care mănâncă absolut toate plantele."]',
'Factorul limitativ în deșertul cald este apa, nu căldura. Doar plantele xerofite, adaptate să reziste la secetă, pot trăi acolo — și de aceea sunt rare.');

-- 198
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a18','9','geografie-fizica','published',2,198,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a18','ro','Care șir așază corect zonele de vegetație pornind de la Ecuator spre pol?',
'["savană -> pădure ecuatorială -> tundră -> taiga","tundră -> taiga -> pădure de foioase -> pădure ecuatorială","pădure ecuatorială -> savană -> pădure de foioase -> taiga -> tundră","mediteraneană -> pădure ecuatorială -> savană -> tundră"]',
'Mergând de la Ecuator spre pol, clima se răcește treptat, iar vegetația o urmează: de la pădurea ecuatorială caldă, prin savană și păduri temperate, până la taiga și tundră.');

-- 199
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a19','9','geografie-fizica','published',1,199,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a19','ro','Dacă, în timp, clima unei regiuni acoperite de pădure de foioase s-ar încălzi și s-ar usca mult, spre ce tip de peisaj ar evolua cel mai probabil?',
'["Spre o pădure ecuatorială deasă.","Spre o stepă cu ierburi, fiindcă precipitațiile mai puține nu ar mai susține pădurea.","Spre o tundră cu plante pitice.","Spre o taiga de conifere."]',
'Dacă scade apa disponibilă, pădurea nu se mai poate menține și lasă locul ierburilor. Așa se explică trecerea firească de la pădurea de foioase la stepă.');

-- 200
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a20','9','geografie-fizica','published',3,200,1783700000000,1783700000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9a1f4c20-1b3d-4e51-8a77-0c2e5f9b1a20','ro','De ce, cunoscând doar clima unui loc, putem prevedea în mare parte ce vegetație și ce animale vom găsi acolo?',
'["Pentru că toate zonele de pe glob au aceleași plante și animale.","Pentru că animalele își aleg singure clima preferată.","Pentru că vegetația nu depinde în niciun fel de climă.","Pentru că clima determină vegetația, iar vegetația determină fauna și solul — toate sunt legate într-un lanț."]',
'Aceasta este ideea centrală a lecției: climă -> vegetație -> faună (și sol). Fiind verigile unui lanț, cunoașterea climei ne lasă să deducem restul.');
